#include <WiFi.h>
#include <WebServer.h>
#include <esp_sleep.h>
#define PIN_LEAK D10
#define PIN_BUTTON D1
#define PIN_LED D2
#define PIN_BUZZER D3
const char* WIFI_SSID="YOUR_SSID";
const char* WIFI_PASS="YOUR_PASSWORD";
WebServer server(80);
bool leakDetected=false,muted=false;
unsigned long muteUntil=0;
RTC_DATA_ATTR unsigned long rtcMuteUntil=0;
void handleRoot(){String h="<!DOCTYPE html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Датчик протечки</title></head><body style='font-family:sans-serif;text-align:center;padding:20px'><h1>Датчик протечки воды</h1>"; if(leakDetected) h+="<h2 style='color:red'>&#9888; ПРОТЕЧКА!</h2>"; else h+="<h2 style='color:green'>Сухо</h2>"; if(muted) h+="<p>Звук приглушен</p>"; h+="<p><a href='/mute'><button>Приглушить 5мин</button></a> <a href='/test'><button>Тест</button></a></p><script>setTimeout(()=>location.reload(),3000)</script></body></html>"; server.send(200,"text/html; charset=utf-8",h);}
void handleMute(){muted=true; muteUntil=millis()+5*60*1000; rtcMuteUntil=millis()+5*60000; server.sendHeader("Location","/"); server.send(303);}
void handleTest(){digitalWrite(PIN_LED,HIGH); digitalWrite(PIN_BUZZER,HIGH); delay(500); digitalWrite(PIN_BUZZER,LOW); digitalWrite(PIN_LED,LOW); server.sendHeader("Location","/"); server.send(303);}
void goSleep(){
  esp_sleep_enable_timer_wakeup(10*1000000ULL);
  esp_deep_sleep_enable_gpio_wakeup(1ULL<<3, ESP_GPIO_WAKEUP_GPIO_LOW);
  esp_deep_sleep_start();
}
void setup(){
  pinMode(PIN_LEAK,INPUT_PULLUP); pinMode(PIN_BUTTON,INPUT_PULLUP); pinMode(PIN_LED,OUTPUT); pinMode(PIN_BUZZER,OUTPUT);
  leakDetected=(digitalRead(PIN_LEAK)==LOW);
  if(!leakDetected){
    WiFi.begin(WIFI_SSID,WIFI_PASS);
    unsigned long t0=millis(); while(WiFi.status()!=WL_CONNECTED && millis()-t0<6000) delay(200);
    server.on("/",handleRoot); server.on("/mute",handleMute); server.on("/test",handleTest); server.begin();
    unsigned long start=millis();
    while(millis()-start<15000){ server.handleClient(); if(digitalRead(PIN_LEAK)==LOW){leakDetected=true; break;} if(digitalRead(PIN_BUTTON)==LOW){digitalWrite(PIN_BUZZER,HIGH); digitalWrite(PIN_LED,HIGH); delay(300); digitalWrite(PIN_BUZZER,LOW); digitalWrite(PIN_LED,LOW); start=millis();} digitalWrite(PIN_LED,(millis()%3000)<100); delay(10); }
    if(!leakDetected) goSleep();
  }
  WiFi.begin(WIFI_SSID,WIFI_PASS);
  unsigned long t0=millis(); while(WiFi.status()!=WL_CONNECTED && millis()-t0<8000) delay(200);
  server.on("/",handleRoot); server.on("/mute",handleMute); server.on("/test",handleTest); server.begin();
  digitalWrite(PIN_BUZZER,HIGH); delay(100); digitalWrite(PIN_BUZZER,LOW);
}
void loop(){
  server.handleClient();
  static unsigned long lastBtn=0;
  if(digitalRead(PIN_BUTTON)==LOW && millis()-lastBtn>500){lastBtn=millis(); if(leakDetected){muted=true; muteUntil=millis()+5*60000;} else {digitalWrite(PIN_BUZZER,HIGH); digitalWrite(PIN_LED,HIGH); delay(300); digitalWrite(PIN_BUZZER,LOW); digitalWrite(PIN_LED,LOW);}}
  if(muted && millis()>muteUntil) muted=false;
  static unsigned long lastCheck=0;
  if(millis()-lastCheck>200){lastCheck=millis(); leakDetected=(digitalRead(PIN_LEAK)==LOW);}
  if(leakDetected && !muted){bool on=(millis()%800)<400; digitalWrite(PIN_BUZZER,on); digitalWrite(PIN_LED,on);} else if(!leakDetected){digitalWrite(PIN_BUZZER,LOW); digitalWrite(PIN_LED,(millis()%3000)<100);} else {digitalWrite(PIN_BUZZER,LOW); digitalWrite(PIN_LED,HIGH);}
  static unsigned long drySince=0;
  if(!leakDetected && !muted){ if(drySince==0) drySince=millis(); if(millis()-drySince>10000) goSleep(); } else drySince=0;
}
